#ifndef MRKENDDO_ROBOT_WEB_UI_H_
#define MRKENDDO_ROBOT_WEB_UI_H_

namespace mrkenddo::web_ui {

static constexpr char kIndexHtml[] = R"WEBUI(<!doctype html>
<html lang="vi">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>MrKenDDo Robot Control</title>
  <style>
    :root{color-scheme:dark;--bg:#08111f;--panel:#101d30;--panel2:#142640;--line:#263b56;--text:#eef6ff;--muted:#8ea3bd;--accent:#37d7b1;--accent2:#5ba7ff;--danger:#ff687d;--shadow:0 18px 55px #0006}
    *{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 0 0,#173453 0,#08111f 42%,#050b13 100%);color:var(--text);font:14px/1.45 system-ui,-apple-system,Segoe UI,sans-serif;min-height:100vh}
    .shell{max-width:1160px;margin:auto;padding:22px}.top{display:flex;justify-content:space-between;gap:16px;align-items:center;margin-bottom:22px}.brand{display:flex;align-items:center;gap:14px}.logo{width:46px;height:46px;border-radius:15px;background:linear-gradient(135deg,var(--accent),var(--accent2));display:grid;place-items:center;color:#06131e;font-weight:900;font-size:20px;box-shadow:0 8px 30px #37d7b144}.eyebrow{color:var(--accent);font-size:11px;letter-spacing:.14em;text-transform:uppercase;font-weight:800}.title{font-size:25px;font-weight:800;letter-spacing:-.03em}.subtitle{color:var(--muted);font-size:12px}.connection{border:1px solid var(--line);background:#0d1a2bcc;border-radius:14px;padding:10px 14px;min-width:185px}.dot{display:inline-block;width:9px;height:9px;border-radius:50%;background:#ffb84d;margin-right:7px;box-shadow:0 0 12px currentColor}.dot.ok{background:var(--accent)}.connection small{color:var(--muted)}
    .grid{display:grid;grid-template-columns:repeat(12,1fr);gap:16px}.card{grid-column:span 6;background:linear-gradient(145deg,#14253cdd,#0e1a2cdd);border:1px solid var(--line);border-radius:20px;padding:18px;box-shadow:var(--shadow);backdrop-filter:blur(10px)}.wide{grid-column:span 12}.third{grid-column:span 4}.card h2{font-size:16px;margin:0 0 4px}.card p{margin:0 0 15px;color:var(--muted);font-size:12px}.card-head{display:flex;justify-content:space-between;align-items:flex-start;gap:10px;margin-bottom:15px}.tag{font-size:11px;color:var(--accent);border:1px solid #37d7b155;background:#37d7b112;border-radius:999px;padding:4px 8px;white-space:nowrap}
    .row{display:flex;gap:10px;align-items:center;flex-wrap:wrap}.field{display:flex;flex-direction:column;gap:6px;flex:1;min-width:115px}.field label{color:var(--muted);font-size:11px}.field input,.field select,textarea{width:100%;border:1px solid var(--line);border-radius:10px;background:#071322;color:var(--text);padding:10px;outline:none}.field input:focus,.field select:focus,textarea:focus{border-color:var(--accent)}textarea{min-height:83px;resize:vertical}.check{display:flex;align-items:center;gap:8px;color:var(--muted);font-size:12px}.check input{accent-color:var(--accent)}
    button{border:0;border-radius:11px;padding:10px 13px;color:var(--text);background:var(--panel2);cursor:pointer;font-weight:700;transition:.15s transform,.15s filter}button:hover{filter:brightness(1.18);transform:translateY(-1px)}button:active{transform:translateY(0)}button:disabled{opacity:.55;cursor:wait}.primary{background:linear-gradient(135deg,#26cda9,#2f9ce5);color:#04131e}.danger{background:#8e2e48}.ghost{background:transparent;border:1px solid var(--line)}.mode.active{background:var(--accent);color:#04131e}.statusline{min-height:19px;margin-top:10px;color:var(--muted);font-size:12px}.statusline.good{color:var(--accent)}.statusline.bad{color:var(--danger)}
    .motor{display:grid;grid-template-columns:repeat(3,1fr);max-width:310px;margin:6px auto 12px;gap:9px}.motor button{height:58px;font-size:20px}.motor .empty{visibility:hidden}.stop{background:var(--danger)}.range{accent-color:var(--accent);width:100%}.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:9px}.stat{padding:12px;border:1px solid var(--line);border-radius:12px;background:#091626}.stat b{display:block;font-size:16px;margin-top:2px}.stat span{color:var(--muted);font-size:11px}.modes{display:flex;gap:7px;flex-wrap:wrap;margin-bottom:12px}.modes button{font-size:12px;padding:8px 10px}.hint{color:var(--muted);font-size:11px;margin-top:9px}.footer{color:#7188a4;text-align:center;font-size:11px;padding:20px 0 4px}.divider{height:1px;background:var(--line);margin:15px 0}
    @media(max-width:800px){.card,.wide,.third{grid-column:span 12}.top{align-items:flex-start;flex-direction:column}.connection{width:100%}.shell{padding:14px}.title{font-size:22px}}
  </style>
</head>
<body>
  <main class="shell">
    <header class="top">
      <div class="brand"><div class="logo">MK</div><div><div class="eyebrow">MrKenDDo · XiaoZhi</div><div class="title">Robot Control Center</div><div class="subtitle">Điều khiển chuyển động, hội thoại và hai màn hình</div></div></div>
      <div class="connection"><span id="dot" class="dot"></span><b id="connection">Đang kiểm tra...</b><br><small id="ip">IP: -</small></div>
    </header>

    <section class="grid">
      <article class="card wide"><div class="card-head"><div><h2>Trạng thái hệ thống</h2><p>Thông tin được cập nhật tự động từ board.</p></div><span class="tag">LIVE</span></div><div class="stats"><div class="stat"><span>Kết nối</span><b id="state">-</b></div><div class="stat"><span>Địa chỉ IP</span><b id="ipStat">-</b></div><div class="stat"><span>Free heap</span><b id="heap">-</b></div></div></article>

      <article class="card"><div class="card-head"><div><h2>Điều khiển robot</h2><p>Giữ cấu hình bước/thời gian ở thẻ bên cạnh.</p></div><span class="tag">MOTION</span></div><div class="motor"><span class="empty"></span><button onclick="move('forward')">▲</button><span class="empty"></span><button onclick="move('left')">◀</button><button class="stop" onclick="stopRobot()">■</button><button onclick="move('right')">▶</button><span class="empty"></span><button onclick="move('backward')">▼</button><span class="empty"></span></div><div id="moveStatus" class="statusline">Sẵn sàng.</div></article>

      <article class="card"><div class="card-head"><div><h2>Cấu hình motor</h2><p>Đảo chiều từng bên theo hướng lắp thực tế.</p></div><span class="tag">SETUP</span></div><div class="row"><div class="field"><label>Đơn vị di chuyển</label><input id="steps" type="number" min="1" max="30000" value="512"></div><div class="field"><label>ms / đơn vị</label><input id="delay" type="number" min="1" max="100" value="1"></div></div><div class="divider"></div><div class="row"><label class="check"><input id="left_inv" type="checkbox"> Đảo motor trái</label><label class="check"><input id="right_inv" type="checkbox" checked> Đảo motor phải</label></div><button class="primary" onclick="saveMotor()" style="margin-top:14px">Lưu cấu hình motor</button><div id="motorStatus" class="statusline"></div></article>

      <article class="card wide"><div class="card-head"><div><h2>Chat với XiaoZhi</h2><p>Gửi câu lệnh qua hàng đợi MCP của firmware; không dùng detect cho văn bản dài.</p></div><span class="tag">MCP</span></div><textarea id="prompt" maxlength="1000" placeholder="Ví dụ: Hãy nói xin chào..."></textarea><div class="row" style="margin-top:10px"><button id="sendPromptButton" class="primary" onclick="sendPrompt()">Gửi câu lệnh</button><span id="promptStatus" class="statusline" style="flex:1;margin:0">Sẵn sàng.</span></div></article>

      <article class="card wide"><div class="card-head"><div><h2>Màn hình phụ OLED</h2><p>Clock, chữ chạy, trạng thái và tắt màn hình. Chữ có dấu được rút gọn về glyph 5×7 để phù hợp bộ nhớ OLED.</p></div><span class="tag">SSD1306</span></div><div class="modes"><button class="mode" data-mode="0" onclick="chooseMode(0)">Đồng hồ</button><button class="mode" data-mode="1" onclick="chooseMode(1)">Chữ chạy</button><button class="mode" data-mode="2" onclick="chooseMode(2)">Trạng thái</button><button class="mode" data-mode="3" onclick="chooseMode(3)">Tắt</button></div><div class="row"><div class="field" style="flex:2"><label>Nội dung chữ chạy</label><input id="oled_text" maxlength="240" placeholder="Xin chào từ MrKenDDo"></div><div class="field"><label>Tốc độ</label><select id="oled_speed"><option value="1">Chậm</option><option value="2" selected>Vừa</option><option value="3">Nhanh</option><option value="4">Rất nhanh</option><option value="5">Cực nhanh</option></select></div><div class="field"><label>Cỡ chữ</label><select id="oled_font"><option value="0">Tự động</option><option value="1">Nhỏ</option><option value="2">Lớn</option></select></div></div><div class="row" style="margin-top:12px"><div class="field"><label>Độ tương phản: <span id="contrastValue">255</span></label><input id="oled_contrast" class="range" type="range" min="0" max="255" value="255" oninput="$('contrastValue').textContent=this.value"></div><label class="check"><input id="oled_invert" type="checkbox"> Đảo màu</label><div class="field" style="max-width:160px"><label>Xoay OLED</label><select id="oled_rotation"><option value="0">0°</option><option value="180">180°</option></select></div></div><div class="row" style="margin-top:14px"><button class="primary" onclick="saveOled()">Lưu & áp dụng</button><button class="ghost" onclick="sendOledMessage()">Chạy chữ ngay</button><button class="ghost" onclick="clearOled()">Xóa màn hình</button><button class="ghost" onclick="testOled()">Khởi tạo lại</button></div><div id="oledStatus" class="statusline"></div><div class="hint">Preset trạng thái hiển thị Wi-Fi/IP và trạng thái hội thoại hiện tại.</div></article>

      <article class="card third"><div class="card-head"><div><h2>Màn hình chính TFT</h2><p>Thiết lập xoay phần mềm.</p></div><span class="tag">ST7789</span></div><div class="field"><label>Góc xoay</label><select id="tft_rotation"><option value="0">0°</option><option value="90">90° · khuyến nghị</option><option value="180">180°</option><option value="270">270°</option></select></div><button class="primary" onclick="saveTft()" style="margin-top:14px">Áp dụng TFT</button><div id="tftStatus" class="statusline"></div></article>
      <article class="card third"><div class="card-head"><div><h2>Thông số OLED</h2><p>I2C và kích thước phần cứng.</p></div><span class="tag">I2C</span></div><div class="row"><div class="field"><label>Địa chỉ hex</label><input id="oled_addr" maxlength="2" value="3C"></div><div class="field"><label>SDA</label><input id="oled_sda" type="number" value="2"></div><div class="field"><label>SCL</label><input id="oled_scl" type="number" value="1"></div></div><div class="row" style="margin-top:10px"><div class="field"><label>Rộng</label><input id="oled_width" type="number" value="128"></div><div class="field"><label>Cao</label><input id="oled_height" type="number" value="32"></div></div></article>
      <article class="card third"><div class="card-head"><div><h2>Ghi chú an toàn</h2><p>HTTP server chỉ nên dùng trong mạng tin cậy.</p></div><span class="tag">LOCAL</span></div><div class="hint">Không forward cổng 80 ra Internet. Khi thử motor, kê robot khỏi mặt đất và dùng thời gian ngắn. LED Control được lược bỏ theo yêu cầu.</div></article>
    </section>
    <div class="footer">MrKenDDo Robot · tenclass.net transport · board-local control panel</div>
  </main>
  <script>
    const $=id=>document.getElementById(id); let selectedMode=0;
    function say(id,text,good=false){$(id).textContent=text;$(id).className='statusline'+(good?' good':'')}
    async function json(url,options={}){const r=await fetch(url,options);let d={};try{d=await r.json()}catch(_){d={error:await r.text()}}if(!r.ok)throw new Error(d.error||'HTTP '+r.status);return d}
    function chooseMode(mode){selectedMode=mode;document.querySelectorAll('.mode').forEach(b=>b.classList.toggle('active',Number(b.dataset.mode)===mode));}
    async function load(){
      try{const d=await json('/api/config');$('steps').value=d.steps;$('delay').value=d.delay_ms;$('left_inv').checked=!!d.left_inverted;$('right_inv').checked=!!d.right_inverted}catch(e){say('motorStatus',e.message)}
      try{const d=await json('/api/oled_config');$('oled_addr').value=d.addr;$('oled_sda').value=d.sda;$('oled_scl').value=d.scl;$('oled_width').value=d.width;$('oled_height').value=d.height;$('oled_rotation').value=d.rotation;$('oled_text').value=d.text||'';$('oled_speed').value=d.speed||2;$('oled_font').value=d.font_size||0;$('oled_contrast').value=d.contrast??255;$('contrastValue').textContent=$('oled_contrast').value;$('oled_invert').checked=!!d.invert;chooseMode(Number(d.mode||0))}catch(e){say('oledStatus',e.message)}
      try{const d=await json('/api/tft_config');$('tft_rotation').value=d.rotation}catch(e){say('tftStatus',e.message)}
      poll();
    }
    async function poll(){try{const d=await json('/api/status');$('dot').classList.toggle('ok',!!d.wifi_connected);$('connection').textContent=d.wifi_connected?'Đã kết nối':'Mất kết nối';$('ip').textContent='IP: '+(d.ip||'-');$('ipStat').textContent=d.ip||'-';$('state').textContent=d.state||'-';$('heap').textContent=d.free_heap?Math.round(d.free_heap/1024)+' KB':'-'}catch(_){$('connection').textContent='Không truy cập được'}setTimeout(poll,2500)}
    async function move(direction){say('moveStatus','Đang chạy '+direction+'...');try{const d=await json('/api/move',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({direction,steps:Number($('steps').value),delay_ms:Number($('delay').value)})});say('moveStatus',d.result||'Đã chạy',true)}catch(e){say('moveStatus',e.message)}}
    async function stopRobot(){try{const d=await json('/api/stop',{method:'POST'});say('moveStatus',d.result||'Đã dừng',true)}catch(e){say('moveStatus',e.message)}}
    async function saveMotor(){try{const d=await json('/api/config',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({steps:Number($('steps').value),delay_ms:Number($('delay').value),left_inverted:$('left_inv').checked,right_inverted:$('right_inv').checked})});say('motorStatus',d.result||'Đã lưu',true)}catch(e){say('motorStatus',e.message)}}
    function oledPayload(){return {addr:$('oled_addr').value.toUpperCase(),sda:Number($('oled_sda').value),scl:Number($('oled_scl').value),width:Number($('oled_width').value),height:Number($('oled_height').value),rotation:Number($('oled_rotation').value),mode:selectedMode,text:$('oled_text').value,speed:Number($('oled_speed').value),font_size:Number($('oled_font').value),contrast:Number($('oled_contrast').value),invert:$('oled_invert').checked}}
    async function saveOled(){try{const d=await json('/api/oled_config',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(oledPayload())});say('oledStatus',d.result||'Đã lưu OLED, đang khởi tạo lại',true)}catch(e){say('oledStatus',e.message)}}
    async function sendOledMessage(){try{const d=await json('/api/oled_message',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({text:$('oled_text').value,speed:Number($('oled_speed').value),font_size:Number($('oled_font').value)})});chooseMode(1);say('oledStatus',d.result||'Đã chạy chữ',true)}catch(e){say('oledStatus',e.message)}}
    async function clearOled(){try{const d=await json('/api/oled_clear',{method:'POST'});chooseMode(3);say('oledStatus',d.result||'Đã xóa OLED',true)}catch(e){say('oledStatus',e.message)}}
    async function testOled(){try{const d=await json('/api/oled_test',{method:'POST'});say('oledStatus',d.result||'Đã khởi tạo lại',true)}catch(e){say('oledStatus',e.message)}}
    async function saveTft(){try{const d=await json('/api/tft_config',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({rotation:Number($('tft_rotation').value)})});say('tftStatus',d.result||'Đã áp dụng',true)}catch(e){say('tftStatus',e.message)}}
    $('prompt').addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key==='Enter')sendPrompt()});
    async function sendPrompt(){const input=$('prompt'),button=$('sendPromptButton'),text=input.value.trim();if(!text)return;button.disabled=true;say('promptStatus','Đang xếp hàng...');try{await json('/api/prompt',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({prompt:text})});say('promptStatus','Đã xếp hàng; chờ MCP consume_pending...');for(let i=0;i<70;i++){await new Promise(r=>setTimeout(r,500));const d=await json('/api/prompt_status');if(d.status==='consumed'){say('promptStatus','MCP đã nhận câu lệnh; chờ XiaoZhi trả lời.',true);input.value='';return}if(d.status==='failed'||d.status==='timeout')throw new Error('Server trả về '+d.status)}throw new Error('Hết thời gian chờ MCP')}catch(e){say('promptStatus',e.message)}finally{button.disabled=false}}
    load();
  </script>
</body>
</html>)WEBUI";

}  // namespace mrkenddo::web_ui

#endif  // MRKENDDO_ROBOT_WEB_UI_H_
